<script>
  document.addEventListener("DOMContentLoaded", function () {
    const molecules = [
        {id: "canvas_Row0", smiles: "CCCCCCCCCCCCCCCCC(CCCCCC)CCCCCCC(=O)OC" },
{id: "canvas_Row1", smiles: "CCCCCCCCCCCCCCCC[C@H](CCCCCC)CCCCCCC(=O)OC" },
{id: "canvas_Row2", smiles: "CCCCCCC(=O)CCCCCCCCCCCCCCCCCCCCCCCCOC(C)=O" }
    ];
    const drawer = new SmilesDrawer.Drawer({ width: 150, height: 150 });
    molecules.forEach(mol => {
      SmilesDrawer.parse(mol.smiles, function (tree) {
        drawer.draw(tree, mol.id, "light", false);
      });
    });
  });
</script>

